window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-be9defb05401e584"]={"versions": [{"id": "FIG-be9defb05401e584", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">GUI-Screenshot eines MATLAB/Simulink-Blockmasken-Dialogs (<code>Function Block Parameters: DataReceiverComSpec_2</code>). Das Schaubild veranschaulicht im Kontext des AUTOSAR-Simulink-Styleguides die Konfiguration eines Hilfsblocks (<code>ComSpec</code>), über den Annotations und Kommunikationsspezifikationen (<code>DataReceiverComSpec</code>) für Software-Komponenten-Ports im Modell hinterlegt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Fenster/Dialog:</strong> Maskenparameter-Dialog <code>DataReceiverComSpec (mask) (link)</code> mit Beschreibungsbereich und Standard-Schaltflächen (<code>OK</code>, <code>Cancel</code>, <code>Help</code>, <code>Apply</code>).\n</li><li><strong>Reiterstruktur (Tabs):</strong> <code>Annotations</code>, <code>ComSpec</code> (aktiv ausgewählt), <code>Extra</code>.\n</li><li><strong>Parameterfelder unter <code>ComSpec</code>:</strong>\n<ul class=\"fig-list\"><li><code>Computed</code>: Dropdown-Auswahl, belegt mit <code>false</code>.\n</li><li><code>LimitType</code>: Dropdown-Auswahl, belegt mit <code>none</code>.\n</li><li><code>Processing type</code>: Dropdown-Auswahl, belegt mit <code>filtered</code>.\n</li><li><code>Signal age</code>: Numerisches Eingabefeld, belegt mit <code>0</code>.\n</li></ul>\n</li><li><strong>Schnittstellenkontext:</strong> Konfiguriert receiverspezifische Kommunikationsattribute (<code>ComSpec</code>), die in die AUTOSAR-SWC-Beschreibung (Software Component Description) und die RTE-API-Generierung für Runnables einfließen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Einstellungsdialog ohne dynamische Ablauf- oder Zeitsequenzen. Der Entwickler wählt im Reiter <code>ComSpec</code> Attribute für die Signalverarbeitung aus (hier: ungefilterte/gefilterte Verarbeitung, Grenztyp und Signalalter), bestätigt die Eingaben über die Masken-Buttons und persistiert damit die Attribute im Simulink-Modell für nachgelagerte Model-to-AUTOSAR-Exportprozesse.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Maskenparameter definieren die semantischen Eigenschaften der AUTOSAR-Kommunikationsspezifikation auf Portebene (<code>DataReceiverComSpec</code>). Fehlkonfigurationen (z. B. unpassende <code>LimitType</code>- oder <code>Processing type</code>-Werte) wirken sich direkt auf die Konsistenz der exportierten Software-Component-Description (SWC-D) und die Schnittstellendefinitionen der generierten RTE-APIs aus. Der Block dient als Träger von Meta- und Kommunikationsinformationen, die nicht direkt in Standard-Simulink-Signalattributen abgebildet werden können.</p>"}, {"id": "FIG-76b2381366db43dd", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">GUI-Screenshot eines MATLAB/Simulink-Blockmasken-Dialogs (<code>Function Block Parameters: DataReceiverComSpec_2</code>). Das Schaubild veranschaulicht im Kontext des AUTOSAR-Simulink-Styleguides die Konfiguration eines Hilfsblocks (<code>ComSpec</code>), über den Annotations und Kommunikationsspezifikationen (<code>DataReceiverComSpec</code>) für Software-Komponenten-Ports im Modell hinterlegt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Fenster/Dialog:</strong> Maskenparameter-Dialog <code>DataReceiverComSpec (mask) (link)</code> mit Beschreibungsbereich und Standard-Schaltflächen (<code>OK</code>, <code>Cancel</code>, <code>Help</code>, <code>Apply</code>).\n</li><li><strong>Reiterstruktur (Tabs):</strong> <code>Annotations</code>, <code>ComSpec</code> (aktiv ausgewählt), <code>Extra</code>.\n</li><li><strong>Parameterfelder unter <code>ComSpec</code>:</strong>\n<ul class=\"fig-list\"><li><code>Computed</code>: Dropdown-Auswahl, belegt mit <code>false</code>.\n</li><li><code>LimitType</code>: Dropdown-Auswahl, belegt mit <code>none</code>.\n</li><li><code>Processing type</code>: Dropdown-Auswahl, belegt mit <code>filtered</code>.\n</li><li><code>Signal age</code>: Numerisches Eingabefeld, belegt mit <code>0</code>.\n</li></ul>\n</li><li><strong>Schnittstellenkontext:</strong> Konfiguriert receiverspezifische Kommunikationsattribute (<code>ComSpec</code>), die in die AUTOSAR-SWC-Beschreibung (Software Component Description) und die RTE-API-Generierung für Runnables einfließen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Einstellungsdialog ohne dynamische Ablauf- oder Zeitsequenzen. Der Entwickler wählt im Reiter <code>ComSpec</code> Attribute für die Signalverarbeitung aus (hier: ungefilterte/gefilterte Verarbeitung, Grenztyp und Signalalter), bestätigt die Eingaben über die Masken-Buttons und persistiert damit die Attribute im Simulink-Modell für nachgelagerte Model-to-AUTOSAR-Exportprozesse.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Maskenparameter definieren die semantischen Eigenschaften der AUTOSAR-Kommunikationsspezifikation auf Portebene (<code>DataReceiverComSpec</code>). Fehlkonfigurationen (z. B. unpassende <code>LimitType</code>- oder <code>Processing type</code>-Werte) wirken sich direkt auf die Konsistenz der exportierten Software-Component-Description (SWC-D) und die Schnittstellendefinitionen der generierten RTE-APIs aus. Der Block dient als Träger von Meta- und Kommunikationsinformationen, die nicht direkt in Standard-Simulink-Signalattributen abgebildet werden können.</p>"}], "trans": [{"from": "FIG-be9defb05401e584", "to": "FIG-76b2381366db43dd", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
